// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.eclipse.rdf4j.sail.lmdb.LmdbPackedRuleDifferentialSupport.check;
import static org.eclipse.rdf4j.sail.lmdb.LmdbPackedRuleDifferentialSupport.checkAndExplain;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.io.File;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * End-to-end guards for the packed MINUS -> correlated NOT EXISTS rewrite on LMDB. The rewrite substitutes the outer
 * row into the MINUS body, which equals MINUS only when every variable the body references is body-local or a shared,
 * assured binding. A body FILTER or nested MINUS that reads a left-only variable, or an outer-scope variable, must keep
 * MINUS semantics whatever the cost model prefers, cold and warm.
 */
class LmdbMinusReferencedVariablesTest {

	private static final String MINUS_HINT = "optimizer.semiAntiKind=minus-assured-shared";

	@Test
	void minusRightFilterReferencingLeftOnlyVariable(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				:a :p 1 ; :q 1 .
				:b :p 2 ; :q 3 .
				""";
		String query = "SELECT ?x ?n WHERE { ?x :p ?n MINUS { ?x :q ?m FILTER(?n = ?m) } }";
		String plan = checkAndExplain(dir, data, query, List.of("n=1|x=urn:t:a", "n=2|x=urn:t:b"));
		assertFalse(plan.contains(MINUS_HINT), "a body reading the left-only ?n must not carry the hint\n" + plan);
	}

	@Test
	void minusRightFilterNotBoundOfLeftOnlyVariable(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				:a :p 1 ; :q 1 .
				:b :p 2 ; :q 3 .
				""";
		String query = "SELECT ?x ?n WHERE { ?x :p ?n MINUS { ?x :q ?m FILTER(!BOUND(?n)) } }";
		check(dir, data, query, List.of());
	}

	@Test
	void minusRightFilterReferencingLeftOnlyVariableLargeRight(@TempDir File dir) throws Exception {
		StringBuilder data = new StringBuilder("@prefix : <urn:t:> .\n:a :p 1 ; :q 1 .\n:b :p 2 ; :q 3 .\n");
		for (int i = 0; i < 3000; i++) {
			data.append(":o").append(i).append(" :q ").append(i + 10).append(" .\n");
		}
		String query = "SELECT ?x ?n WHERE { ?x :p ?n MINUS { ?x :q ?m FILTER(?n = ?m) } }";
		check(dir, data.toString(), query, List.of("n=1|x=urn:t:a", "n=2|x=urn:t:b"));
	}

	@Test
	void minusRightFilterReferencingLeftOnlyVariableLargeRightTypedLeft(@TempDir File dir) throws Exception {
		StringBuilder data = new StringBuilder(
				"@prefix : <urn:t:> .\n:a a :L ; :p 1 ; :q 1 .\n:b a :L ; :p 2 ; :q 3 .\n");
		for (int i = 0; i < 3000; i++) {
			data.append(":o")
					.append(i)
					.append(" :q ")
					.append(i + 10)
					.append(" ; :p ")
					.append(i + 10)
					.append(" .\n");
		}
		String query = "SELECT ?x ?n WHERE { ?x a :L ; :p ?n MINUS { ?x :q ?m FILTER(?n = ?m) } }";
		check(dir, data.toString(), query, List.of("n=1|x=urn:t:a", "n=2|x=urn:t:b"));
	}

	/** The reviewer's confirmed end-to-end red: a tiny VALUES-anchored left side makes the anti-join cheapest. */
	@Test
	void minusSmallLeftLargeRightFilterOnLeftOnlyVariable(@TempDir File dir) throws Exception {
		StringBuilder data = new StringBuilder("@prefix : <urn:t:> .\n:a :p 1 ; :q 1 .\n:b :p 2 ; :q 3 .\n");
		for (int i = 0; i < 3000; i++) {
			data.append(":o").append(i).append(" :q ").append(i + 10).append(" .\n");
		}
		String query = "SELECT ?x ?n WHERE { VALUES ?x { :a :b } ?x :p ?n MINUS { ?x :q ?m FILTER(?n = ?m) } }";
		String plan = checkAndExplain(dir, data.toString(), query, List.of("n=1|x=urn:t:a", "n=2|x=urn:t:b"));
		assertFalse(plan.contains(MINUS_HINT), "a body reading the left-only ?n must not carry the hint\n" + plan);
	}

	@Test
	void minusSmallLeftLargeRightNestedMinus(@TempDir File dir) throws Exception {
		StringBuilder data = new StringBuilder("@prefix : <urn:t:> .\n:a :p 1 ; :q 5 ; :r 7 .\n");
		for (int i = 0; i < 3000; i++) {
			data.append(":o").append(i).append(" :q ").append(i + 10).append(" ; :r ").append(i).append(" .\n");
		}
		String query = "SELECT ?x ?n WHERE { VALUES ?x { :a } ?x :p ?n MINUS { ?x :q ?m MINUS { ?x :r ?n } } }";
		String plan = checkAndExplain(dir, data.toString(), query, List.of("n=1|x=urn:t:a"));
		assertFalse(plan.contains(MINUS_HINT),
				"a nested MINUS right side reading the left-only ?n must not carry the hint\n" + plan);
	}

	/**
	 * {@code ?y} is bound by the enclosing join, not by the MINUS left side; SPARQL evaluates the MINUS group with
	 * {@code ?y} unbound (the body FILTER errors, the body is empty, the row survives).
	 */
	@Test
	void minusSmallLeftLargeRightFilterOnOuterScopeVariable(@TempDir File dir) throws Exception {
		StringBuilder data = new StringBuilder("@prefix : <urn:t:> .\n:a :p 1 ; :q 1 .\n:z :s :a .\n");
		for (int i = 0; i < 3000; i++) {
			data.append(":o").append(i).append(" :q ").append(i + 10).append(" .\n");
		}
		String query = "SELECT ?y ?x ?n WHERE { ?y :s ?x . "
				+ "{ VALUES ?x { :a } ?x :p ?n MINUS { ?x :q ?m FILTER(?m = ?y) } } }";
		String plan = checkAndExplain(dir, data.toString(), query, List.of("n=1|x=urn:t:a|y=urn:t:z"));
		assertFalse(plan.contains(MINUS_HINT),
				"a body reading the outer-scope ?y must not carry the hint\n" + plan);
	}

	/** A nested MINUS right side that reads only the shared name is substitution-equivalent and stays correct. */
	@Test
	void minusSmallLeftLargeRightNestedMinusOnSharedVariableOnly(@TempDir File dir) throws Exception {
		StringBuilder data = new StringBuilder(
				"@prefix : <urn:t:> .\n:e1 :dosage 1 .\n:p1 :hasMedication :e1 .\n:e2 :dosage 2 .\n");
		for (int i = 0; i < 3000; i++) {
			data.append(":o").append(i).append(" :dosage ").append(i + 10).append(" .\n");
		}
		String query = "SELECT ?entity WHERE { VALUES ?entity { :e1 :e2 } "
				+ "MINUS { ?entity :dosage ?dose MINUS { ?patient :hasMedication ?entity } } }";
		check(dir, data.toString(), query, List.of("entity=urn:t:e1"));
	}

	/**
	 * The body BIND reads the shared {@code ?x} before the body binds it, so on its own the BIND leaves {@code ?y}
	 * unbound and every {@code ?x :q ?y} row is compatible: a/1 is removed.
	 */
	@Test
	void minusSmallLeftLargeRightBindReadsSharedVariableBeforeItIsBound(@TempDir File dir) throws Exception {
		StringBuilder data = new StringBuilder("@prefix : <urn:t:> .\n:a :p 1 ; :q :b .\n");
		for (int i = 0; i < 3000; i++) {
			data.append(":o").append(i).append(" :q :o").append(i + 1).append(" .\n");
		}
		String query = "SELECT ?x ?n WHERE { VALUES ?x { :a } ?x :p ?n MINUS { BIND(?x AS ?y) ?x :q ?y } }";
		String plan = checkAndExplain(dir, data.toString(), query, List.of());
		assertFalse(plan.contains(MINUS_HINT),
				"a body BIND reading the shared ?x before it is bound must not carry the hint\n" + plan);
	}
}
